/*
 * A076631  Solve 2^n - 2 = 7(x^2 - x) + (y^2 - y) for (x,y) with x>0, y>0;
 *          a(n) = value of y.
 * https://oeis.org/A076631
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   The pair (u,v) = (2y-1 , 2x-1) satisfies u² + 7v² = 2ⁿ⁺².
 *            Starting with u = v = 1 (n = 1) the unique solution for index n
 *            is generated by u' = (u - 7 v) / 2 v' = (u + v) / 2 After n–1
 *            steps, the answer y is y = (|u| + 1) / 2 . The computation uses
 *            128‑bit signed intermediates so that unsigned ove...
 * Range:     u8 n <= 17, u16 n <= 33, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

seq_t a(idx_t n)
{
    /* unsigned key is avoided – we keep all arithmetic in __int128 */
    __int128 u = 1;   /* u = 2y – 1 */
    __int128 v = 1;   /* v = 2x – 1 */

    /* iterate the recurrence (n‑1) times */
    for (idx_t i = 1; i < n; ++i) {
        __int128 new_u = (u - (__int128)7 * v) / 2;
        __int128 new_v = (u + v) / 2;
        u = new_u;
        v = new_v;
    }

    /* absolute value of u */
    __int128 abs_u = u >= 0 ? u : -u;

    /* compute y = (|u| + 1)/2 and cast back to seq_t */
    return (seq_t)((abs_u + 1) / 2);
}
